/// <summary>
/// MPJ_34360_TransferOrderReceipt
/// This class register for transfer orders as per the data in metTOReceipts entity.
/// </summary>
class METPostTOReceiptService extends SysOperationServiceBase
{
    str          errorMessage;
    str          infologMessage;

}

Method.Source:
    /// <summary>
    /// Executes the business logic
    /// </summary>
    /// <param name = "_contract"><c>metpostTOReceiptContract</c> class instance</param>
    private void runOperation(METPostTOReceiptContract    _contract)
    {
        int                 bundlesize, noOfReceipts, totalTasks, i, j, task;
        List                receiptList      = new List(Types::String);
        metTOReceipt        metTOReceipt;
        Set                 transferOrderSet = new Set(Types::String);

        BatchHeader batchHeader = this.getCurrentBatchHeader();

        task = 1;

        totalTasks      =   _contract.parmTasks();
        if (totalTasks <= 0)
        {
            totalTasks = 1;
        }
        if (batchHeader == null)
        {
            batchHeader = batchHeader::construct();
        }

        batchHeader.parmCaption("@MET:METPostTOReceiptBatchJob");

        while select metTOReceipt group by TransferOrderNumber, ReceiptNumber
            where metTOReceipt.Error == NoYes::No
        {
            if(!transferOrderSet.in(metTOReceipt.TransferOrderNumber))
            {
                transferOrderSet.add(metTOReceipt.TransferOrderNumber);
            }
            else
            {
                this.updateDuplicateLogLine(metTOReceipt.TransferOrderNumber);
            }
        }

        while select RecId from metTOReceipt
            group by ReceiptNumber
            where metTOReceipt.Error == NoYes::No
        {
            noOfReceipts++;
        }

        bundleSize      =   real2int(roundUp((noOfReceipts / totalTasks), 1.0));

        while select metTOReceipt
             group by ReceiptNumber
            where metTOReceipt.Error == NoYes::No
        {
            i++;
            j++;

            receiptList.addEnd(metTOReceipt.ReceiptNumber);

            if(i == bundlesize || j == noOfReceipts)
            {
                SysOperationServiceController postTOReceiptController = new SysOperationServiceController(
                                                                classStr(metpostTOReceiptService),
                                                                methodStr(metpostTOReceiptService, postTOReceiptSubTask));

                postTOReceiptController.parmDialogCaption(strFmt("@MET:METTOSubTask", task));

                metpostTOReceiptContract postTOReceiptcontract = postTOReceiptController.getDataContractObject() as metpostTOReceiptContract;
                postTOReceiptcontract.parmReceiptList(receiptList);

                batchHeader.addRuntimeTask(postTOReceiptController, this.getCurrentBatchTask().RecId);
                receiptList = new List(Types::String);
                task++;
                i = 0;
            }
        }

        batchHeader.save();

    }

    /// <summary>
    /// Gets the latest infolog error message
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;

        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());
        infologMessage = METConstants::emptyString;

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }

    /// <summary>
    /// update the error message to metTORecipts buffer
    /// </summary>
    /// <param name = "_mbsErrorMsg">actual error message</param>
    /// <param name = "_mbsInfologMsg">infolog error message</param>
    /// <param name = "_ReceiptNumber">the metTOReceipt ReceiptNumber to be updated with the error message </param>
    private void updateLogLine(str _mbsErrorMsg, str _mbsInfologMsg, METTOReceiptNumber _ReceiptNumber)
    {

        metTOReceipt metTOReceiptLoc;

        ttsbegin;
        while select forupdate Error, ErrorMessage, ProcessedDate
            from metTOReceiptLoc
            where metTOReceiptLoc.ReceiptNumber == _ReceiptNumber
        {
            metTOReceiptLoc.Error = NoYes::Yes;
            metTOReceiptLoc.ErrorMessage = _mbsErrorMsg + _mbsInfologMsg;
            metTOReceiptLoc.ProcessedDate = DateTimeUtil::getSystemDateTime();
            metTOReceiptLoc.doUpdate();
        }
        ttscommit;
    }

    /// <summary>
    /// update the error message to metTORecipts buffer
    /// </summary>
    /// <param name = "_transferId">transfer order number</param>
    private void updateDuplicateLogLine(InventTransferId _transferId)
    {

        metTOReceipt metTOReceiptLoc;

        ttsbegin;
        while select forupdate Error, ErrorMessage, ProcessedDate
            from metTOReceiptLoc
            where metTOReceiptLoc.TransferOrderNumber == _transferId
        {
            metTOReceiptLoc.Error = NoYes::Yes;
            metTOReceiptLoc.ErrorMessage = strFmt("@MET:METTOMultiReceiptError", _transferId);
            metTOReceiptLoc.ProcessedDate = DateTimeUtil::getSystemDateTime();
            metTOReceiptLoc.doUpdate();
        }
        ttscommit;
    }

    /// <summary>
    /// Performs the actual operation of regisering transfer order.
    /// </summary>
    /// <param name = "_contract"><c>metpostTOReceiptContract</c> class instance.</param>
    private void postTOReceiptSubTask(metpostTOReceiptContract    _contract)
    {
        #OCCRetryCount

        boolean                 isError, isRegistrationSuccessful;
        ListEnumerator          receiptListEnumerator;
        METTOReceiptNumber      ReceiptNumber;
        metTOReceipt            metTOReceipt, metTOReceiptLoc;
        InventTransferLine      InventTransferLine, InventTransferLineToSplit;
        utcdatetime             ReceiptDate;
        boolean                 isCWItem;
        Qty                     receiveQty, qtyToSplit;
        RecId                   transferLineRecId;
        InventTransferTable     InventTransferTable;

        receiptListEnumerator      = _contract.parmReceiptList().getEnumerator();

        while (receiptListEnumerator.moveNext())
        {
            try
            {
                ttsBegin;

                ReceiptNumber = receiptListEnumerator.current();
                ReceiptDate = utcDateTimeNull();
                isError = false;
                isCWItem = false;

                while select metTOReceipt
                group by TransferOrderNumber, ReceiptDate, ReceiptNumber, ItemNumber, ReceiveQty, CWReceiveQty, LineNumber, ReceivingWarehouseId
                    where metTOReceipt.Error == NoYes::No 
                       && metTOReceipt.ReceiptNumber == ReceiptNumber
                {
                    InventTransferTable = InventTransferTable::find(metTOReceipt.TransferOrderNumber);
                    if(!InventTransferTable.RecId)
                    {
                        throw Error(strFmt("@MET:METTONotFoundError", metTOReceipt.TransferOrderNumber));
                    }
                    else if(InventTransferTable.TransferStatus != InventTransferStatus::Shipped)
                    {
                        throw Error(strFmt("@MET:METTOShipStatusError", metTOReceipt.TransferOrderNumber));
                    }
                    ReceiptDate = metTOReceipt.ReceiptDate;

                    [transferLineRecId, receiveQty, qtyToSplit, isCWItem] = this.getInventTransferLine(metTOReceipt);
                    
                    select firstonly InventTransferLine
                            where InventTransferLine.RecId == transferLineRecId;

                    if(InventTransferLine.RecId)
                    {
                        isRegistrationSuccessful = this.registerInventTransferLine(InventTransferLine, receiveQty, metTOReceipt, isCWItem);
                        if(!isRegistrationSuccessful)
                        {
                            throw Error("@MET:METTORegisterError");
                        }

                        if(qtyToSplit > 0)
                        {
                            select firstonly RecId from InventTransferLineToSplit
                                where InventTransferLineToSplit.TransferId == metTOReceipt.TransferOrderNumber
                                    && InventTransferLineToSplit.ItemId == metTOReceipt.ItemNumber
                                    && InventTransferLineToSplit.QtyTransfer >= qtyToSplit
                                    && InventTransferLineToSplit.LineNum != InventTransferLine.LineNum;

                            if(InventTransferLineToSplit.RecId)
                            {
                                isRegistrationSuccessful = this.registerInventTransferLine(InventTransferLine, qtyToSplit, metTOReceipt, isCWItem);
                                if(!isRegistrationSuccessful)
                                {
                                    throw Error("@MET:METTORegisterError");
                                }
                            }
                        }
                    }
                    else
                    {
                        throw Error(strFmt("@MET:METTONoLineError",metTOReceipt.ItemNumber, metTOReceipt.TransferOrderNumber));
                    }
                }

                if(!isError)
                {
                    delete_from metTOReceiptLoc
                        where metTOReceiptLoc.ReceiptNumber == ReceiptNumber
                           && metTOReceiptLoc.ReceiptDate == ReceiptDate;
                }
                ttscommit;
            }
            catch (Exception::Error)
            {
                errorMessage    = METConstants::emptyString;
                this.getInfologMessage();
                System.Exception ex = CLRInterop::getLastException();
                if (ex != null)
                {
                    errorMessage += ex.Message + ex.ToString();
                }
                this.updateLogLine(errorMessage, infologMessage, ReceiptNumber);
            }
            catch (Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    errorMessage    = "@MET:METTODeadlockError";
                    this.getInfologMessage();
                    this.updateLogLine(errorMessage, infologMessage, ReceiptNumber);
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        errorMessage    = "@MET:METTOUpdConflictError";
                        this.getInfologMessage();
                        this.updateLogLine(errorMessage, infologMessage, ReceiptNumber);
                        isError = true;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    errorMessage    = "@MET:METTOUpdConflictError";
                    this.getInfologMessage();
                    this.updateLogLine(errorMessage, infologMessage, ReceiptNumber);
                    isError = true;
                }
            }
        }

    }

    /// <summary>
    /// Method to identify the transfer line against which the quantity will be recieved
    /// </summary>
    /// <param name = "_metTOReceipt">metTOReceipt buffer</param>
    /// <returns>transfer line that matches the criteria</returns>
    public container getInventTransferLine(metTOReceipt _metTOReceipt)
    {
        InventTransferLine                       InventTransferLine, InventTransferLineCount, InventTransferLineToSplit, InventTransferLineCW;
        Qty                             qtyToSplit, receiveQty;
        UnitOfMeasureSymbol             warehouseUnit, transferUnit, inventoryUnit;
        UnitOfMeasureConversionFactor   conversionFactor;
        InventDim                       inventDim, inventDimCount;
        InventTableModule               inventTableModule;
        EcoResProduct                   ecoResProduct;
        InventTable                     inventTable;
        boolean                         isCWItem;        

        select count(RecId) from InventTransferLineCount
            where InventTransferLineCount.TransferId == _metTOReceipt.TransferOrderNumber
                    && InventTransferLineCount.ItemId == _metTOReceipt.ItemNumber
                    && InventTransferLineCount.LineNum == _metTOReceipt.LineNumber
            join RecId from inventDimCount
            where inventDimCount.inventDimId == InventTransferLineCount.InventDimId
                    && inventDimCount.InventLocationId == _metTOReceipt.ReceivingWarehouseId;

        if(InventTransferLineCount.RecId >= 1)
        {
            select firstonly InventTransferLine
                where InventTransferLine.TransferId == _metTOReceipt.TransferOrderNumber
                    && InventTransferLine.ItemId == _metTOReceipt.ItemNumber
                    && InventTransferLine.LineNum == _metTOReceipt.LineNumber
                join RecId from inventDim
                where inventDim.inventDimId == InventTransferLine.InventDimId
                    && inventDim.InventLocationId == _metTOReceipt.ReceivingWarehouseId;

            
            select firstonly PdsCWProduct from ecoResProduct
                join inventTable
                    where inventTable.ItemId == _metTOReceipt.ItemNumber
                        && inventTable.Product == ecoResProduct.RecId;

            if(ecoResProduct.PdsCWProduct)
            {
                receiveQty = _metTOReceipt.ReceiveQty;
                isCWItem = true;

                select firstonly InventTransferLineCW
                    where InventTransferLineCW.TransferId == _metTOReceipt.TransferOrderNumber
                        && InventTransferLineCW.ItemId == _metTOReceipt.ItemNumber
                        && InventTransferLineCW.PdsCWQtyTransfer >= receiveQty
                    join RecId from inventDim
                    where inventDim.inventDimId == InventTransferLineCW.InventDimId
                        && inventDim.InventLocationId == _metTOReceipt.ReceivingWarehouseId;

                if(InventTransferLineCW.RecId)
                {
                    return [InventTransferLineCW.RecId, receiveQty, 0, isCWItem];
                }
                else if (InventTransferLine.OverDeliveryPct > 0) //Check if overdelivery is allowed
                {
                    Qty maxReceivedQty = InventTransferLine.QtyTransfer * (1 + InventTransferLine.OverDeliveryPct / 100);

                    if(maxReceivedQty >= receiveQty)
                    {
                        return [InventTransferLine.RecId, receiveQty, 0, isCWItem];
                    }
                }
            }
            else
            {
                warehouseUnit = InventTransferLine.MetWarehouseUnitId;
                transferUnit = InventTransferLine.UnitId;

                select firstonly UnitId from inventTableModule
                            where inventTableModule.ItemId      == InventTransferLine.ItemId
                               && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

                if(inventTableModule.UnitId)
                {
                    inventoryUnit = inventTableModule.UnitId;
                }

                // Calculate the transfer qty from the warehouse quantity
                if(warehouseUnit == transferUnit)
                {
                    receiveQty = _metTOReceipt.ReceiveQty;
                }
                else if(warehouseUnit == METConstants::emptyString)
                {
                    receiveQty = _metTOReceipt.ReceiveQty;
                }
                else
                {
                    conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                                UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                                UnitOfMeasure::findBySymbol(transferUnit).RecId,
                        EcoResProduct::findByProductNumber(InventTransferLine.ItemId).RecId)
                                .Factor, 0);

                    if(conversionFactor != 0)
                    {
                        if(transferUnit == inventoryUnit)
                        {
                            receiveQty = _metTOReceipt.ReceiveQty * conversionFactor;
                        }
                        else
                        {
                            receiveQty = _metTOReceipt.ReceiveQty / conversionFactor;
                        }
                    }
                    else
                    {
                        conversionFactor = roundUp(UnitOfMeasureConversion::findByConversion(
                                    UnitOfMeasure::findBySymbol(transferUnit).RecId,
                                    UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                                    EcoResProduct::findByProductNumber(InventTransferLine.ItemId).RecId)
                                    .Factor, 0);

                        if(conversionFactor != 0)
                        {
                            if(transferUnit == inventoryUnit)
                            {
                                receiveQty = _metTOReceipt.ReceiveQty * conversionFactor;
                            }
                            else
                            {
                                receiveQty = _metTOReceipt.ReceiveQty / conversionFactor;
                            }
                        }
                        else
                        {
                            throw Error(strFmt("@MET:METTOConversionError", InventTransferLine.ItemId, warehouseUnit, transferUnit));
                        }
                    }
                }

                select firstonly InventTransferLine
                        where InventTransferLine.TransferId == _metTOReceipt.TransferOrderNumber
                            && InventTransferLine.ItemId == _metTOReceipt.ItemNumber
                        join RecId from inventDim
                    where inventDim.inventDimId == InventTransferLine.InventDimId
                        && inventDim.InventLocationId == _metTOReceipt.ReceivingWarehouseId;

                if(InventTransferLine.RecId)
                {
                    if(InventTransferLine.QtyTransfer >=receiveQty) //Check if quantities match
                    {
                        return [InventTransferLine.RecId,receiveQty, 0, isCWItem];
                    }
                    else
                    {
                        if(InventTransferLineCount.RecId > 1)  //try to split the lines
                        {
                            qtyToSplit =receiveQty - InventTransferLine.QtyTransfer;

                            select firstonly RecId from InventTransferLineToSplit
                                where InventTransferLineToSplit.TransferId == _metTOReceipt.TransferOrderNumber
                                    && InventTransferLineToSplit.ItemId == _metTOReceipt.ItemNumber
                                    && InventTransferLineToSplit.QtyTransfer >= qtyToSplit
                                    && InventTransferLineToSplit.LineNum != InventTransferLine.LineNum
                                join RecId from inventDim
                                    where inventDim.inventDimId == InventTransferLineToSplit.InventDimId
                                    && inventDim.InventLocationId == _metTOReceipt.ReceivingWarehouseId;

                            if(InventTransferLineToSplit.RecId)
                            {
                                return [InventTransferLine.RecId,receiveQty, qtyToSplit, isCWItem];
                            }

                        }
                        else if((InventTransferLineCount.RecId == 1))
                        {
                            if (InventTransferLine.OverDeliveryPct > 0) //Check if overdelivery is allowed
                            {
                                Qty maxReceivedQty = InventTransferLine.QtyTransfer * (1 + InventTransferLine.OverDeliveryPct / 100);

                                if(maxReceivedQty >=receiveQty)
                                {
                                    return [InventTransferLine.RecId,receiveQty, 0, isCWItem];
                                }
                            }
                        }
                    }
                }
            }
        }
        return [InventTransferLine.RecId,receiveQty, 0, isCWItem];
    }

   /// <summary>
   /// This method is used to register a transfer line
   /// </summary>
   /// <param name = "_InventTransferLine">the transfer line record</param>
   /// <param name = "_receiveQty">the quantity to be registered</param>
    /// <param name = "_metTOReceipt">the metTOReceipt buffer</param>
   /// <param name = "isCWItem">boolean value indicating CW item</param>
   /// <returns>true if registration is successful</returns>
    public boolean registerInventTransferLine(InventTransferLine _InventTransferLine, Qty _receiveQty, metTOReceipt _metTOReceipt, boolean isCWItem)
    {
        InventTrans             inventTrans;
        InventTransWMS_Register inventTransWMS_register;
        TmpInventTransWMS       tmpInventTransWMS;
        UnitOfMeasureSymbol     inventoryUnit;
        InventTableModule       inventTableModule;
        boolean                 ret;

        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId      == _InventTransferLine.ItemId
               && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        inventTrans = InventTrans::findTransId(_InventTransferLine.InventTransIdReceive);

        if(inventTrans && inventTrans.StatusReceipt != StatusReceipt::Registered)
        {
            if(isCWItem)
            {
                inventTrans.PdsCWQty = _receiveQty;
                inventTrans.Qty = _metTOReceipt.CWReceiveQty;
            }
            else
            {
                if(_InventTransferLine.UnitId == inventoryUnit)
                {
                    inventTrans.Qty = _receiveQty;
                }
                else
                {
                    inventTrans.Qty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_InventTransferLine.ItemId, _InventTransferLine.InventDimId, _receiveQty, _InventTransferLine.UnitId, InventTable::find(_InventTransferLine.itemId).inventUnitId(), NoYes::Yes);
                }
            }
            
            inventTransWMS_Register = InventTransWMS_Register::newStandard(tmpInventTransWMS);
            inventTransWMS_Register.createFromInventTrans(inventTrans, inventTrans.inventDim());
            ret = inventTransWMS_Register.updateInvent(_InventTransferLine);
        }
        return ret;
    }
